  try{ r=mastApplyScores(items,plan.ids.map(id=>({id})),plan.scores,pn,mastDrillSettings(),{prevShown:new Set(),autoPull:false,chain:false}); }
  finally{ masteryKid=_mk; }
  const upd={}; (r.touched||[]).forEach(it=>{ const ix=items.indexOf(it); if(ix<0) return;
    upd[ix+"/tier"]=it.tier; upd[ix+"/consecutive_correct"]=it.consecutive_correct||0; upd[ix+"/cycle"]=it.cycle||1; upd[ix+"/drop_count"]=it.drop_count||0;
    upd[ix+"/status"]=it.status||"active"; upd[ix+"/tally_dots"]=it.tally_dots??0; upd[ix+"/next_due"]=it.next_due??null;
    upd[ix+"/dynamic"]=it.dynamic?true:null; upd[ix+"/dynSource"]=it.dynamic?(it.dynSource||null):null; upd[ix+"/dynFromTier"]=it.dynamic?(it.dynFromTier||null):null; upd[ix+"/dynAddedAt"]=it.dynamic?(it.dynAddedAt||null):null;
    if(it.ww) upd[ix+"/ww"]=it.ww; });
