  const D=notYet?null:((typeof envDrillDecks==="function")?envDrillDecks(kid):null);
  if(!D){ if(!_cplnt.timer&&(++_cplnt.tries)<=CPLNT_TRIES&&typeof setTimeout==="function") _cplnt.timer=setTimeout(()=>{ _cplnt.timer=null; cplntCatchUp(kid); },CPLNT_RETRY_MS); return 0; }
