// CPCLASS_START — 🏫 THE CLASS RECORD AND ITS LOOK, per class (DESIGN_class_platform_2026-10-28.md §3, §9, §13 row 2, §15; PR 2 of the
// class platform). Her words 2026-10-28: "the teacher can change that and it reflects on the students and the parents' page, and then
// they don't have that option at all … customize it by the name and maybe the emoji and then the color that she wants it to be … per
// class, instead of kids being able to change theirs" · "give her lots of options because this will also be used for other classes" ·
// the build: "lets get these built". INERT unless ENVSITE's envEdition() says "envirothon": every function returns at once otherwise,
// and Howe, DeWalt and Burris never reach one (their boot is byte-identical — test_env_site.js, test_cp_class.js).
//   · THE CLASS RECORD (classes/<cid> on the shared instance) gains: title (the name under "Howe Academy" on every bar; was the
//     literal "Envirothon") · emoji · color (#rrggbb, the bar for the whole class) · season (was ENVS_SEASON) · start · goals [{name,
//     date, note}] · goal {name, pct} (the one the pace target aims at, PR 8) · lockAt (the class closes after it; was ENVS_AUTOLOCK)
//     · calendar {days, off} · labels (the class's own words, §15) · features (optional parts, §15). Every one is optional: a class
//     without it reads today's value.
//   · THE BARS: kid "🌿 Maya · Envirothon", parent "🌿 Maya's Envirothon", teacher "🌿 Envirothon · MS Science 2026-27", every one
//     under the Howe Academy wordmark, on the class's color. cpTextOn picks white or black words (whichever reads better; one of
//     the two always reaches 4.58 : 1), and the small "Academy", the stars, "N students" and the bar's buttons follow it. Before the
//     class has arrived, a kid's bar shows the host config's className on the default green (the same fallback as today).
//   · 🏫 CLASS SETUP (a console chip, teacher + admin): 🎨 the look (title, 42 emojis + any one emoji, 42 swatches = 21 hues dark
//     and light + any color, a live preview of the kid's and the parent's bar; nothing saved until Save) · 📅 the season (season,
//     start, goal dates, the goal the pace aims at) · 🗓 study days · 🔤 words and features · 🔒 when the class closes (Adrienne's;
//     the teacher sees it). classes/<cid>/locks/brand (Adrienne's, from PR 15) greys the look for the teacher, "🔒 set by Adrienne".
//   · ADRIENNE'S + CLASS form gains title, season, start, a goal date and the lock date.
//   · WRITES: one targeted update at classes/<cid> per Save (only that card's fields), through envcWrite → envsWrite (demo: a "would
//     update" toast; dry run: nothing); + Class is one multi-path update (classes/<cid> + teachers/<uid>/classes/<cid>), as before.
//     The rules (envirothon/SITE_RULES.json) give the teacher per-child writes under classes/<cid>; lockAt, name, teacher and locks
//     stay Adrienne's.
//   · THE LOCK DATE: envsLockState reads the class's lockAt in place of ENVS_AUTOLOCK; a class past its date lands on the
//     "season closed" card (kid, parent, teacher) the moment the class record arrives.
const CP_HUES=[["Red","#991b1b","#fecaca"],["Orange","#9a3412","#fed7aa"],["Amber","#92400e","#fde68a"],["Yellow","#854d0e","#fef08a"],["Lime","#3f6212","#d9f99d"],["Green","#166534","#bbf7d0"],["Forest","#2d6a4f","#d8f3dc"],["Emerald","#065f46","#a7f3d0"],["Teal","#115e59","#99f6e4"],["Cyan","#155e75","#a5f3fc"],["Sky","#075985","#bae6fd"],["Blue","#1e40af","#bfdbfe"],["Indigo","#3730a3","#c7d2fe"],["Violet","#5b21b6","#ddd6fe"],["Purple","#6b21a8","#e9d5ff"],["Fuchsia","#86198f","#f5d0fe"],["Pink","#9d174d","#fbcfe8"],["Rose","#9f1239","#fecdd3"],["Brown","#5c3d2e","#ead7c3"],["Slate","#1e293b","#e2e8f0"],["Stone","#44403c","#e7e5e4"]];
const CP_EMOJI="\u{1F33F} \u{1F332} \u{1F333} \u{1F30A} \u{1F989} \u{1F98C} \u{1F41D} \u{1F98B} \u{1F43E} \u{1F30D} \u{1F52C} \u{1F9EA} \u{1F9EC} \u{1F52D} \u{1FA90} \u{1F30B} ⛰️ \u{1F9ED} \u{1F5FA}️ \u{1F3DB}️ \u{1F4DC} \u{1F3FA} ⚔️ \u{1F5FD} \u{1F54A}️ ⚖️ \u{1F4DA} \u{1F4D6} ✏️ \u{1F4D0} \u{1F9EE} \u{1F4A1} \u{1F9E0} \u{1F3A8} \u{1F3B5} \u{1F3AD} \u{1F5E3}️ ✍️ \u{1F3C6} \u{1F680} ⚙️ \u{1F34E}".split(" ");
const CP_DEF={title:"Envirothon",emoji:"\u{1F33F}",color:"#14532d"};   // today's bar: the literal, the leaf, the console's green
// §15 the words: a unit's own (NC Envirothon's until PR 3 puts labels on the unit) ← the class's; a plain default when a unit gives none
const CP_LABELS_PLAIN={section:"Section",sections:"Sections",pre:"Pre-test",post:"Post-test",item:"item",concept:"Topic"};
const CP_LABELS_UNIT={section:"Station",sections:"Stations",pre:"Check-in",post:"Final",item:"species",concept:"Key Concept"};
const CP_LABEL_ROWS=[["section","One section is called"],["sections","More than one"],["pre","The test before"],["post","The test after"],["item","One ID item is called"],["concept","A topic is called"]];
const CP_FEATURES=[["teams","\u{1F3C6} Teams","the team board, the effort board, team picks"],["boards","\u{1F4CA} Boards","the class boards students and parents see"],["specialists","\u{1F3C5} Specialists","a student can be the class's master of one section"],["idFlash","⚡ ID Flash","picture flash for ID items"],["mockRun","⏱️ Mock run","a timed practice run of the whole event"]];
const CP_FEATURES_UNIT={teams:true,boards:true,specialists:true,idFlash:true,mockRun:false};   // NC Envirothon's, until PR 3 (the unit) carries them
const CP_CAL_DAYS=[["school","Each family's own study days"],["noWeekends","Weekdays, days off skipped"],["weekdays","Monday to Friday"],["every","Every day"]];
const CP_MONTHS=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
const _cp={css:false,cid:"",d:null,words:false};
function cpOn(){ return typeof envSiteOn==="function"&&envSiteOn(); }
function cpEsc(v){ return envsEsc(v); }
// the class this screen is about: the console's own (teacher / admin), else the kid's or parent's (ENVSITE envsReadShared, the demo's seed)
function cpCls(){ if(!cpOn()) return null; try{ if((_envs.role==="teacher"||_envs.role==="admin")&&typeof _envc!=="undefined"&&_envc.cls) return _envc.cls; }catch(e){} return _envs.cls||null; }
// ── PURE: colors ──
function cpHex(c){ const m=/^#?([0-9a-f]{6})$/i.exec(String(c==null?"":c).trim()); return m?"#"+m[1].toLowerCase():""; }
function cpLum(hex){ const h=cpHex(hex); if(!h) return 0; return [1,3,5].map(i=>parseInt(h.slice(i,i+2),16)/255).map(x=>x<=0.03928?x/12.92:Math.pow((x+0.055)/1.055,2.4)).reduce((s,x,i)=>s+x*[0.2126,0.7152,0.0722][i],0); }
function cpContrast(a,b){ const x=cpLum(a), y=cpLum(b); return (Math.max(x,y)+0.05)/(Math.min(x,y)+0.05); }
// white or black words, whichever gives more contrast. Pure black, not the app's near-black: with #1f2937 some mid greens drop to 3.8 : 1.
function cpTextOn(bg){ return cpContrast(bg,"#ffffff")>=cpContrast(bg,"#000000")?"#ffffff":"#000000"; }
// the wordmark's "Academy": today's indigo on a dark bar when it still reads (4.5 : 1), else the words' own color
function cpAccentOn(bg){ const ink=cpTextOn(bg), c=ink==="#ffffff"?["#a5b4fc","#c7d2fe","#e0e7ff"]:["#312e81"]; for(let i=0;i<c.length;i++){ if(cpContrast(bg,c[i])>=4.5) return c[i]; } return ink; }
// ── PURE: the fields ──
function cpTitleOk(s){ s=String(s==null?"":s).trim(); return s.length>=1&&s.length<=40&&!/[\u0000-\u001f<>]/.test(s); }
// one emoji: a picture character, no letters or digits, one grapheme where the browser can count them, at most 16 code units (the rules' cap)
function cpEmojiOk(s){ s=String(s==null?"":s).trim(); if(!s||s.length>16||/[A-Za-z0-9<>&"'\s]/.test(s)) return false;
  try{ if(!/\p{Extended_Pictographic}|\p{Regional_Indicator}/u.test(s)) return false; }catch(e){}
  try{ if(typeof Intl!=="undefined"&&Intl.Segmenter){ let n=0; for(const x of new Intl.Segmenter().segment(s)){ if(++n>1) return false; } } }catch(e){}
  return true; }
