function cpLabel(key,cls){ cls=cls===undefined?cpCls():cls; const L=(cls&&cls.labels)||{}; const v=String(L[key]==null?"":L[key]).trim(); return v||(typeof cpuLabel==="function"&&cpuLabel(key,cls))||CP_LABELS_UNIT[key]||CP_LABELS_PLAIN[key]||String(key||""); }   // 📦 CPUNIT: the unit's own word under the class's
function cpFeature(name,cls){ cls=cls===undefined?cpCls():cls; const F=(cls&&cls.features)||{}; if(typeof F[name]==="boolean") return F[name]; const u=(typeof cpuFeature==="function")?cpuFeature(name,cls):null; if(u!=null) return u; return CP_FEATURES_UNIT[name]===true; }   // 📦 CPUNIT: the unit's features under the class's
function cpSeason(cls){ cls=cls===undefined?cpCls():cls; const s=cls&&(cls.season||cls.year); return s?String(s):(typeof ENVS_SEASON!=="undefined"?ENVS_SEASON:""); }
// the class's lock date as ENVSITE's day key ("YYYYMMDD"); "" = no date of its own (ENVS_AUTOLOCK stays). lockAt undefined = the current class's.
function cpLockKey(lockAt){ if(lockAt===undefined){ if(!cpOn()) return ""; const c=cpCls(); lockAt=c&&c.lockAt; } return cpDateOk(lockAt)?String(lockAt).replace(/-/g,""):""; }
