// ── 🏫 CLASS SETUP (teacher + admin) ──
function cpAdmin(){ return typeof envcAdmin==="function"&&envcAdmin(); }
function cpBrandLocked(cls){ cls=cls===undefined?cpCls():cls; return !!(cls&&cls.locks&&cls.locks.brand===true); }
// PURE: a class → the setup draft (every field the screen edits)
function cpDraftOf(cls){
  cls=cls||{}; const b=cpBrand(cls), g=Array.isArray(cls.goals)?cls.goals:(cls.goals&&typeof cls.goals==="object"?Object.keys(cls.goals).sort((a,c)=>a-c).map(k=>cls.goals[k]):[]), cal=cls.calendar||{};
  return {title:b.title,emoji:b.emoji,color:b.color,name:String(cls.name||""),season:cpSeason(cls),start:String(cls.start||""),
    goals:g.filter(Boolean).map(x=>({name:String(x.name||""),date:String(x.date||""),note:String(x.note||"")})),goalName:String((cls.goal&&cls.goal.name)||""),goalPct:(cls.goal&&cls.goal.pct!=null)?String(cls.goal.pct):"95",
    days:CP_CAL_DAYS.some(x=>x[0]===cal.days)?cal.days:"school",off:Object.assign({},cal.off||{}),labels:Object.assign({},cls.labels||{}),
    features:Object.fromEntries(CP_FEATURES.map(f=>[f[0],cpFeature(f[0],cls)])),lockAt:String(cls.lockAt||"")};
}
// PURE: one card of the draft → {ok, upd (the fields that card saves, at classes/<cid>), error}
function cpCheck(part,d){
  d=d||{}; const bad=e=>({ok:false,error:e});
  if(part==="look"){
    if(!cpTitleOk(d.title)) return bad("A title of 1 to 40 characters, please.");
    if(!cpEmojiOk(d.emoji)) return bad("Pick one emoji.");
    const c=cpHex(d.color); if(!c) return bad("Pick a color.");
    return {ok:true,upd:{title:String(d.title).trim(),emoji:String(d.emoji).trim(),color:c}}; }
  if(part==="season"){
    const s=String(d.season||"").trim(); if(!s||s.length>20) return bad("A season of 1 to 20 characters, e.g. 2026-27.");
    if(d.start&&!cpDateOk(d.start)) return bad("The start date isn't a date.");
    const goals=[], seen={};
    for(const x of (d.goals||[])){ const n=String(x.name||"").trim(), dt=String(x.date||""); if(!n&&!dt) continue;
      if(!n||n.length>40) return bad("Each goal date needs a name (up to 40 characters)."); if(!cpDateOk(dt)) return bad("“"+n+"” needs a date.");
      if(seen[n.toLowerCase()]) return bad("Two goal dates are called “"+n+"”."); seen[n.toLowerCase()]=1;
      const g={name:n,date:dt}; const note=String(x.note||"").trim(); if(note) g.note=note.slice(0,120); goals.push(g); }
    let goal=null;
    if(goals.length){ const name=goals.some(g=>g.name===d.goalName)?d.goalName:goals[0].name, p=Number(d.goalPct);
      if(!Number.isInteger(p)||p<1||p>100) return bad("The target is a whole percent, 1 to 100."); goal={name,pct:p}; }
    return {ok:true,upd:{season:s,start:d.start||null,goals:goals.length?goals:null,goal}}; }
  if(part==="days"){
    if(!CP_CAL_DAYS.some(x=>x[0]===d.days)) return bad("Pick the study days.");
    const off={}; Object.keys(d.off||{}).forEach(k=>{ if(d.off[k]&&cpDateOk(k)) off[k]=true; });
    const cal={days:d.days}; if(Object.keys(off).length) cal.off=off; return {ok:true,upd:{calendar:cal}}; }
  if(part==="words"){
    const labels={}; for(const r of CP_LABEL_ROWS){ const v=String((d.labels||{})[r[0]]||"").trim(); if(v.length>30) return bad("A word is at most 30 characters."); if(v&&v!==CP_LABELS_UNIT[r[0]]) labels[r[0]]=v; }
    const features={}; CP_FEATURES.forEach(f=>{ features[f[0]]=!!(d.features||{})[f[0]]; });
    return {ok:true,upd:{labels:Object.keys(labels).length?labels:null,features}}; }
  if(part==="close"){
    const n=String(d.name||"").trim(); if(!n||n.length>60) return bad("The class's name, 1 to 60 characters.");
    if(d.lockAt&&!cpDateOk(d.lockAt)) return bad("The closing date isn't a date.");
    return {ok:true,upd:{name:n,lockAt:d.lockAt||null}}; }
  return bad("Unknown part");
}
function cpCan(part){ if(typeof envcOn!=="function"||!envcOn()) return false; if(cpAdmin()) return true; if(part==="close") return false; if(part==="look") return !cpBrandLocked(); return true; }
function cpDraft(){ const cid=(typeof _envc!=="undefined"&&_envc.cid)||""; if(!_cp.d||_cp.cid!==cid){ _cp.cid=cid; _cp.d=cpDraftOf(cpCls()); } return _cp.d; }
// a field changed: "prev" repaints only the preview (typing keeps its focus), true repaints the screen, nothing = just remember it
function cpSet(k,v,re){ if(!cpOn()) return; const d=cpDraft(); d[k]=v;
  if(re==="prev"){ try{ const p=document.getElementById("cp-prev"); if(p) p.innerHTML=cpPrevHtml(d); }catch(e){} } else if(re) envcRe(); }
function cpEmojiType(v){ v=String(v||"").trim(); if(!v) return; if(!cpEmojiOk(v)){ envsToast("One emoji, please (no letters)."); return; } cpSet("emoji",v,true); }
// (no repaint on a typed change: a repaint while the box loses focus would swallow the tap on Save)
function cpGoal(i,k,v){ const d=cpDraft(); if(d.goals[i]) d.goals[i][k]=v; }
function cpGoalAdd(){ const d=cpDraft(); d.goals.push({name:"",date:"",note:""}); envcRe(); }
function cpGoalDel(i){ const d=cpDraft(); d.goals.splice(i,1); envcRe(); }
function cpOffAdd(){ const d=cpDraft(), v=((document.getElementById("cp-off-new")||{}).value||"").trim(); if(!cpDateOk(v)){ envsToast("Pick a date first."); return; } d.off[v]=true; envcRe(); }
function cpOffDel(k){ const d=cpDraft(); delete d.off[k]; envcRe(); }
function cpFeat(k,on){ const d=cpDraft(); d.features[k]=!!on; }
function cpWord(k,v){ const d=cpDraft(); d.labels[k]=v; }
// Cancel (and after a Save): that card's fields back to the class's; the other cards keep what is being typed
const CP_PART_KEYS={look:["title","emoji","color"],season:["season","start","goals","goalName","goalPct"],days:["days","off"],words:["labels","features"],close:["name","lockAt"]};
function cpRedraft(part){ const d=cpDraft(), f=cpDraftOf(cpCls()); (CP_PART_KEYS[part]||[]).forEach(k=>{ d[k]=f[k]; }); }
function cpCancel(part){ cpRedraft(part); envcRe(); }
// THE save: one targeted update at classes/<cid> with that card's fields (null clears one). The console's memory takes it at once (the demo's
// state IS this object, shared with the kid's and parent's bars; live, the classes/<cid> listener confirms it a moment later).
function cpSave(part){
  if(typeof envcOn!=="function"||!envcOn()||!_envc.cid) return false;
  if(!cpCan(part)){ envsToast(part==="look"?"\u{1F512} The class's look is set by "+(typeof cpLockName==="function"?cpLockName():"Adrienne"):"\u{1F512} Only Adrienne changes this"); return false; }
  const c=cpCheck(part,cpDraft()); if(!c.ok){ envsToast(c.error); return false; }
  const upd=c.upd;
  envcWrite("classes/"+_envc.cid,upd,"update").then(()=>{ const cls=_envc.cls||(_envc.cls={}); Object.keys(upd).forEach(k=>{ if(upd[k]==null) delete cls[k]; else cls[k]=upd[k]; }); if(!_envs.cls) _envs.cls=cls; cpRedraft(part); if(part==="close") cpClassIn(); envcRe(); }).catch(()=>{});
  return true;
}
// the live preview: the kid's and the parent's bar exactly as they will paint, plus the words' contrast
function cpPrevHtml(d){
  const b=cpBrand({title:d.title,emoji:d.emoji,color:d.color}), who=cpPrevName(), ok=cpTitleOk(d.title)&&cpEmojiOk(d.emoji);
  const fake=x=>'<span class="cp-fake">'+x+'</span>', star=fake("⭐ 27");
  return cpBarHtml(b,cpLine("kid",b,who),star,fake("⚙️"),true)+cpBarHtml(b,cpLine("parent",b,who),"",fake("⚙️"),true)+
    '<div class="envs-muted">Words: <b>'+(b.ink==="#000000"?'black':'white')+'</b> · contrast '+cpContrast(b.color,b.ink).toFixed(1)+' : 1 · '+cpEsc(b.color)+(ok?'':' · <span style="color:#b91c1c">check the title and the emoji</span>')+'</div>';
}
function cpPrevName(){ try{ if(envsDemo()&&_envs.kid) return String(envsKidName(_envs.kid)).split(" ")[0]; const s=(typeof envcStudents==="function")?envcStudents():[]; const n=s.length&&s[0].meta&&s[0].meta.name; if(n) return String(n).split(" ")[0]; }catch(e){} return "Maya"; }
function cpCardHead(t,sub){ return '<div class="envs-h2" style="margin-bottom:2px">'+t+'</div>'+(sub?'<div class="envs-muted" style="margin-bottom:6px">'+sub+'</div>':''); }
function cpActs(part,can){ const dis=can?'':' disabled'; return '<div class="envs-row" style="margin-top:10px"><button class="envs-btn cp-btn" onclick="cpSave(\''+part+'\')"'+dis+'>Save</button><button class="envs-btn sec cp-btn" onclick="cpCancel(\''+part+'\')"'+dis+'>Cancel</button></div>'; }
function cpLookHtml(d){
  const can=cpCan("look"), dis=can?'':' disabled', lk=cpBrandLocked();
  let h='<div class="envs-card">'+cpCardHead("\u{1F3A8} The class’s look","The title, emoji and bar color. Students and parents see them on every bar and can’t change them. Nothing is saved until Save.");
  if(lk) h+='<div class="envs-chip" style="background:#fffbeb;border-color:#fcd34d;color:#92400e;margin-bottom:6px">\u{1F512} '+(cpAdmin()?'Locked for the teacher':'Set by '+(typeof cpLockName==="function"?cpLockName():'Adrienne'))+'</div>';   // 🔒 CPLOCKS: the admin's own name
  h+='<div class="cp-lbl">Preview</div><div id="cp-prev">'+cpPrevHtml(d)+'</div>';
  h+='<div class="cp-lbl">Title</div><input id="cp-title" class="envs-in" maxlength="40" value="'+cpEsc(d.title)+'"'+dis+' oninput="cpSet(\'title\',this.value,\'prev\')" onchange="cpSet(\'title\',this.value)">';
  h+='<div class="cp-lbl">Emoji</div><div class="cp-em">'+CP_EMOJI.map(e=>'<button class="'+(d.emoji===e?'on':'')+'"'+dis+' onclick="cpSet(\'emoji\',\''+e+'\',true)" aria-label="'+e+'">'+e+'</button>').join("")+'</div>';
  h+='<input id="cp-emoji" class="envs-in" style="width:220px" maxlength="16" placeholder="or type any one emoji"'+dis+' onchange="cpEmojiType(this.value)">';
  h+='<div class="cp-lbl">Bar color · '+CP_HUES.length+' colors, each dark or light</div><div class="cp-sw">'+CP_HUES.map(x=>[1,2].map(i=>'<button class="'+(d.color===x[i]?'on':'')+'" title="'+x[0]+(i===1?' dark':' light')+'" aria-label="'+x[0]+(i===1?' dark':' light')+'" style="background:'+x[i]+';color:'+cpTextOn(x[i])+'"'+dis+' onclick="cpSet(\'color\',\''+x[i]+'\',true)">Aa</button>').join("")).join("")+'</div>';
  h+='<label class="envs-row" style="font-size:13.5px;font-weight:700">Any color <input id="cp-color" type="color" value="'+cpEsc(d.color)+'" style="width:56px;height:40px;border:none;background:none"'+dis+' oninput="cpSet(\'color\',this.value,\'prev\')" onchange="cpSet(\'color\',this.value,true)"></label>';
  h+='<div class="envs-muted" style="margin-top:4px">Every color gets black or white words, whichever is easier to read, so a light color never hides the title.</div>';
  return h+cpActs("look",can)+'</div>';
}
function cpSeasonHtml(d){
  const can=cpCan("season"), dis=can?'':' disabled', J=envcJ;
  let h='<div class="envs-card">'+cpCardHead("\u{1F4C5} The season","The season shows on the © line; the goal dates are what the pace aims at.");
  h+='<div class="envs-row"><div style="flex:1;min-width:130px"><div class="cp-lbl">Season</div><input id="cp-season" class="envs-in" maxlength="20" value="'+cpEsc(d.season)+'"'+dis+' onchange="cpSet(\'season\',this.value)"></div><div style="flex:1;min-width:150px"><div class="cp-lbl">First study day</div><input id="cp-start" class="envs-in" type="date" value="'+cpEsc(d.start)+'"'+dis+' onchange="cpSet(\'start\',this.value)"></div></div>';
  h+='<div class="cp-lbl">Goal dates</div>';
  if(!d.goals.length) h+='<div class="envs-muted">None yet. Add the day of the competition, the exam or the bee.</div>';
  d.goals.forEach((g,i)=>{ h+='<div class="envs-row" style="padding:3px 0"><input class="envs-in" style="flex:1;min-width:110px" maxlength="40" placeholder="Name (Area)" value="'+cpEsc(g.name)+'"'+dis+' onchange="cpGoal('+i+',\'name\',this.value)"><input class="envs-in" style="width:160px" type="date" value="'+cpEsc(g.date)+'"'+dis+' onchange="cpGoal('+i+',\'date\',this.value)"><input class="envs-in" style="flex:2;min-width:140px" maxlength="120" placeholder="note (optional)" value="'+cpEsc(g.note)+'"'+dis+' onchange="cpGoal('+i+',\'note\',this.value)"><button class="envs-btn sec cp-btn" style="min-height:40px;padding:0 12px"'+dis+' onclick="cpGoalDel('+i+')" aria-label="Remove">✕</button></div>'; });
  h+='<button class="envs-btn sec cp-btn" style="margin-top:4px"'+dis+' onclick="cpGoalAdd()">+ Goal date</button>';
  const named=d.goals.filter(g=>String(g.name||"").trim());
  if(named.length){ const cur=named.some(g=>g.name===d.goalName)?d.goalName:named[0].name;
    h+='<div class="cp-lbl">The pace aims at</div><div class="envs-row">'+named.map(g=>'<button class="envs-btn cp-btn '+(g.name===cur?'':'sec')+'" style="min-height:36px;padding:0 12px"'+dis+' onclick="cpSet(\'goalName\',\''+J(g.name)+'\',true)">'+cpEsc(g.name)+'</button>').join("")+'<label class="envs-row" style="font-size:13px">with <input class="envs-in" style="width:76px" type="number" inputmode="numeric" min="1" max="100" value="'+cpEsc(d.goalPct)+'"'+dis+' onchange="cpSet(\'goalPct\',this.value)"> % of the core cards learned</label></div>'; }
  return h+cpActs("season",can)+'</div>';
}
function cpDaysHtml(d){
  const can=cpCan("days"), dis=can?'':' disabled', offs=Object.keys(d.off||{}).filter(k=>d.off[k]).sort();
  let h='<div class="envs-card">'+cpCardHead("\u{1F5D3} Study days","The class’s default. The pace planner counts these days.");
  h+='<div class="envs-row">'+CP_CAL_DAYS.map(x=>'<button class="envs-btn cp-btn '+(d.days===x[0]?'':'sec')+'" style="min-height:38px;padding:0 12px"'+dis+' onclick="cpSet(\'days\',\''+x[0]+'\',true)">'+cpEsc(x[1])+'</button>').join("")+'</div>';
  h+='<div class="cp-lbl">Days off</div><div class="envs-row">'+(offs.length?offs.map(k=>'<span class="envs-chip">'+cpEsc(cpDateLabel(k))+(can?' <a href="javascript:void(0)" onclick="cpOffDel(\''+k+'\')" style="color:#b91c1c;text-decoration:none" aria-label="Remove">✕</a>':'')+'</span>').join(""):'<span class="envs-muted">None</span>')+'</div>';
  h+='<div class="envs-row" style="margin-top:6px"><input id="cp-off-new" class="envs-in" style="width:170px" type="date"'+dis+'><button class="envs-btn sec cp-btn"'+dis+' onclick="cpOffAdd()">+ Day off</button></div>';
  return h+cpActs("days",can)+'</div>';
}
function cpWordsHtml(d){
  const can=cpCan("words"), dis=can?'':' disabled';
  let h='<div class="envs-card"><div class="envs-row"><div style="flex:1">'+cpCardHead("\u{1F524} Words and features","What the class calls its parts, and which optional parts it uses.")+'</div><button class="envs-btn sec" onclick="_cp.words=!_cp.words;envcRe()">'+(_cp.words?'▴ Close':'▾ Open')+'</button></div>';
  if(!_cp.words) return h+'</div>';
  h+=CP_LABEL_ROWS.map(r=>'<div class="envs-row" style="padding:3px 0"><div style="flex:1;min-width:150px;font-size:13px">'+cpEsc(r[1])+'</div><input class="envs-in" style="width:170px" maxlength="30" placeholder="'+cpEsc(CP_LABELS_UNIT[r[0]])+'" value="'+cpEsc((d.labels||{})[r[0]]||"")+'"'+dis+' onchange="cpWord(\''+r[0]+'\',this.value)"></div>').join("");
  h+='<div class="envs-muted" style="margin:2px 0 8px">Blank = the unit’s word.</div>';
  h+=CP_FEATURES.map(f=>'<label class="envs-row" style="padding:4px 0;min-height:40px;font-size:13px"><input type="checkbox" '+((d.features||{})[f[0]]?'checked':'')+dis+' onchange="cpFeat(\''+f[0]+'\',this.checked)"> <b>'+cpEsc(f[1])+'</b> <span class="envs-muted">'+cpEsc(f[2])+'</span></label>').join("");
  return h+cpActs("words",can)+'</div>';
}
function cpCloseHtml(d){
  const admin=cpAdmin(), dis=admin?'':' disabled', lbl=cpDateLabel(d.lockAt)||(typeof envsAutoLockLabel==="function"?envsAutoLockLabel():"");
  let h='<div class="envs-card">'+cpCardHead("\u{1F512} The class closes","After this date the class lands on “season closed” for the teacher and every family. Nothing is deleted."+(admin?'':' Set by Adrienne.'));
  h+='<div class="envs-row"><div style="flex:2;min-width:160px"><div class="cp-lbl">Class name</div><input id="cp-name" class="envs-in" maxlength="60" value="'+cpEsc(d.name)+'"'+dis+' onchange="cpSet(\'name\',this.value)"></div><div style="flex:1;min-width:160px"><div class="cp-lbl">Closes after</div><input id="cp-lockat" class="envs-in" type="date" value="'+cpEsc(d.lockAt)+'"'+dis+' onchange="cpSet(\'lockAt\',this.value)"></div></div>';
  h+='<div class="envs-muted" style="margin-top:4px">Now: closes after <b>'+cpEsc(lbl)+'</b>'+(d.lockAt?'':' (the site’s date)')+'. The master lock (\u{1F511} Admin) still closes every class at once.</div>';
  return h+(admin?cpActs("close",true):'')+'</div>';
}
function cpSetupHtml(){
  if(typeof envcOn!=="function"||!envcOn()) return ""; cpCss(); const cls=_envc.cls||{}, d=cpDraft();
  let h='<div class="envs-card">'+cpCardHead("\u{1F3EB} Class setup · "+cpEsc(cls.name||_envc.cid),"Saved at classes/"+cpEsc(_envc.cid)+". Students and parents see the change the next time their page paints.")+'</div>';
  return h+cpLookHtml(d)+cpSeasonHtml(d)+cpDaysHtml(d)+cpWordsHtml(d)+((typeof cpuSetupHtml==="function")?cpuSetupHtml():"")+((typeof cpFinalPlanHtml==="function")?cpFinalPlanHtml():"")+cpCloseHtml(d)+((typeof cpSkillSetupHtml==="function")?cpSkillSetupHtml():"");   // 📦 CPUNIT: the class's units · 📝 CPFINAL: the section plan · 🧩 CPSKILL: the class's skills
}
// ── Adrienne's + Class (envcAdminHtml's Classes card; envcClassAdd) ──
// PURE: the form → {ok, cid, rec, error}. The look starts at today's (the teacher sets her own in 🏫 Class setup).
function cpNewClass(f){
  f=f||{}; const cid=String(f.id||"").toLowerCase().replace(/[^a-z0-9-]/g,""), name=String(f.name||"").trim(), title=String(f.title||"").trim()||CP_DEF.title, season=String(f.season||"").trim()||cpSeason(null);
  if(!cid||!name) return {ok:false,error:"Class id and name, please."};
  if(!cpTitleOk(title)) return {ok:false,error:"A title of 1 to 40 characters, please."};
  if(f.start&&!cpDateOk(f.start)) return {ok:false,error:"The start date isn't a date."};
  if(f.lockAt&&!cpDateOk(f.lockAt)) return {ok:false,error:"The closing date isn't a date."};
  const gn=String(f.goalName||"").trim(); if(gn&&!cpDateOk(f.goalDate)) return {ok:false,error:"“"+gn+"” needs a date."};
  const rec={name,title,emoji:CP_DEF.emoji,color:CP_DEF.color,season,year:season,area:8,division:"ms",students:{}};
  if(f.start) rec.start=f.start; if(gn){ rec.goals=[{name:gn.slice(0,40),date:f.goalDate}]; rec.goal={name:gn.slice(0,40),pct:95}; } if(f.lockAt) rec.lockAt=f.lockAt; if(f.teacher) rec.teacher=String(f.teacher).trim();
  return {ok:true,cid,rec};
}
function cpAdminClassHtml(){
  if(!cpAdmin()) return ""; const cls=Object.keys(_envc.classes||{});
  return '<div class="envs-card"><div class="envs-h2">Classes</div><div class="envs-chips" style="padding-bottom:0">'+cls.map(c=>'<button class="'+(_envc.cid===c?'on':'')+'" onclick="envcPickClass(\''+envcJ(c)+'\')">'+envcEsc((_envc.classes[c]&&_envc.classes[c].name)||c)+'</button>').join("")+'</div>'+
    '<div class="cp-lbl" style="margin-top:10px">+ Class</div><div class="envs-row"><input id="envc-cls-id" class="envs-in" style="width:170px" placeholder="class id (ms-science-2026)"><input id="envc-cls-name" class="envs-in" style="flex:1;min-width:140px" placeholder="Class name"><input id="envc-cls-teacher" class="envs-in" style="flex:1;min-width:160px" placeholder="teacher uid"></div>'+
    '<div class="envs-row" style="margin-top:6px"><input id="cp-new-title" class="envs-in" style="flex:1;min-width:150px" maxlength="40" placeholder="Title on every bar ('+cpEsc(CP_DEF.title)+')"><input id="cp-new-season" class="envs-in" style="width:110px" maxlength="20" placeholder="season" value="'+cpEsc(cpSeason(null))+'"><label class="envs-muted">first study day <input id="cp-new-start" class="envs-in" style="width:160px" type="date"></label></div>'+
    ((typeof cpuNewUnitsHtml==="function")?cpuNewUnitsHtml():"")+// 📦 CPUNIT: + Class ticks the units
    '<div class="envs-row" style="margin-top:6px"><input id="cp-new-goal" class="envs-in" style="width:150px" maxlength="40" placeholder="goal (Area)"><input id="cp-new-goaldate" class="envs-in" style="width:160px" type="date"><label class="envs-muted">closes after <input id="cp-new-lockat" class="envs-in" style="width:160px" type="date" value="'+cpEsc(typeof ENVS_AUTOLOCK!=="undefined"?ENVS_AUTOLOCK.slice(0,4)+"-"+ENVS_AUTOLOCK.slice(4,6)+"-"+ENVS_AUTOLOCK.slice(6,8):"")+'"></label><button class="envs-btn sec" onclick="envcClassAdd()">+ Class</button></div>'+
    '<div class="envs-muted" style="margin-top:4px">Writes classes/&lt;id&gt; = {name, title, emoji, color, season, start, goals, goal, lockAt, students}. The teacher sets the look, the season and the study days in \u{1F3EB} Class setup.</div></div>';
}
function cpClassAdd(){
  if(!cpAdmin()) return false; const g=id=>((document.getElementById(id)||{}).value||"").trim();
  const c=cpNewClass({id:g("envc-cls-id"),name:g("envc-cls-name"),teacher:g("envc-cls-teacher"),title:g("cp-new-title"),season:g("cp-new-season"),start:g("cp-new-start"),goalName:g("cp-new-goal"),goalDate:g("cp-new-goaldate"),lockAt:g("cp-new-lockat")});
  if(!c.ok){ envsToast(c.error); return false; }
  if(typeof cpuNewUnits==="function") c.rec.units=cpuNewUnits();   // 📦 CPUNIT: the units ticked
  const o={["classes/"+c.cid]:c.rec}; if(c.rec.teacher) o["teachers/"+c.rec.teacher+"/classes/"+c.cid]=true;
  envcMulti(o,"Class made").then(()=>{ if(envsDemo()){ _envc.classes[c.cid]=c.rec; } envcPickClass(c.cid); }).catch(()=>{});
  return true;
}
// ── the demo: the sample class gets the look and the season (NC Envirothon's real dates), so every bar reads the class record ──
function cpDemoStart(data){
  if(!data||!data.cls) return; _cp.d=null; _cp.cid=""; _cp.words=false;
  Object.assign(data.cls,{title:"Envirothon",emoji:"\u{1F33F}",color:"#2d6a4f",season:"2026-27",start:"2026-09-15",
    goals:[{name:"Area",date:"2027-03-22"},{name:"State",date:"2027-04-23",note:"top 7 MS teams at Area qualify"}],goal:{name:"Area",pct:95},
    lockAt:"2027-04-24",calendar:{days:"school",off:{"2026-11-26":true,"2026-12-24":true,"2026-12-25":true}},features:Object.assign({},CP_FEATURES_UNIT)});
}
