const _cpu={cat:{},load:{},watch:{}};
function cpuOn(){ return typeof envSiteOn==="function"&&envSiteOn(); }
function cpuCls(){ if(!cpuOn()) return null; return (typeof cpCls==="function")?cpCls():(_envs.cls||null); }
function cpuEsc(v){ return envsEsc(v); }
