// ── PURE: dates (YYYY-MM-DD at UTC midnight) and weekday sets ("1234" = Mon–Thu; 0 = Sunday) ──
function cpcalOk(s){ s=String(s==null?"":s); if(!/^\d{4}-\d{2}-\d{2}$/.test(s)) return false; return new Date(Date.UTC(+s.slice(0,4),+s.slice(5,7)-1,+s.slice(8,10))).toISOString().slice(0,10)===s; }
function cpcalMs(s){ return Date.UTC(+s.slice(0,4),+s.slice(5,7)-1,+s.slice(8,10)); }
