function cpGoalList(cls){ const g=(typeof cppGoals==="function")?cppGoals(cls||{}):[], want=cls&&cls.goal&&cls.goal.name, t=g.some(x=>x.name===want)?want:(g[0]?g[0].name:"");
  return g.map(x=>({name:String(x.name),date:String(x.date),note:String(x.note||""),target:x.name===t})); }
