function cpcoCpWhat(c){ return c.n!=null?cpcoNum(c.n)+" core cards":c.pct+"% of the core cards"; }
function cpcoCpShort(c){ return (c.n!=null?cpcoNum(c.n):c.pct+"%")+" by "+cpcalShort(c.date); }
