      if(_cpsg.aside) h+=aside.map(k=>'<div class="envs-row" style="align-items:center;margin-top:6px"><div class="cpsg-w" style="flex:1;min-width:160px;margin:0">'+cpsgEsc(now[k]||D[k].t||k)+'</div><button class="envs-btn sec" style="min-height:36px;padding:0 11px;font-size:12.5px;margin:0" onclick="cpsgBack(\''+cpsgJ(k)+'\')">↩ Bring back</button></div>').join("");
