        const x={i:C.length,id:dk.key+"#o"+order,deck:dk.key,di,o:order,sec:st.id,kind,name:String(c.name),def:String(c.def==null?"":c.def),src:String(c.src||""),info:String(c.info||""),item:String(c.item||""),core:!!c.core};
        if(kind==="id"){ const k=x.item||String(c.name).split(" · ")[0]; if(!iBy[k]){ iBy[k]={key:st.id+"|id|"+sec.items.length,label:k,cards:[]}; sec.items.push(iBy[k]); } x.g=iBy[k]; iBy[k].cards.push(x); }
        else { const gl=String(c.group||c.family||"Other"); if(!gBy[gl]){ gBy[gl]={key:st.id+"|g"+sec.groups.length,label:gl,ord:Number.isFinite(+c.concept)&&c.concept!==""&&c.concept!=null?+c.concept:1e6+sec.groups.length,first:sec.groups.length,cards:[]}; sec.groups.push(gBy[gl]); } x.g=gBy[gl]; gBy[gl].cards.push(x); }
