function cpcsCntHtml(o,total){ return '<div class="cpcs-cnt"><span><b>'+cpcsN(o.n)+'</b>'+(total!=null&&total!==o.n?' of '+cpcsN(total):'')+' card'+((total!=null?total:o.n)===1?'':'s')+'</span>'+(o.core?'<span>⭐ '+cpcsN(o.core)+'</span>':'')+(typeof cpceCntHtml==="function"?cpceCntHtml(o):'')+'</div>'; }   // 📚 CPCARDSEDIT
// ── the taps: one open at each level, and moving on folds back what she left
function cpcsTap(level,id){
  if(!cpcsOn()) return;
  const S=_cpcs;
  if(level==="st"){ S.os=S.os===id?null:id; S.og=S.osp=S.or=null; S.more={}; }
  else if(level==="grp"){ S.og=S.og===id?null:id; S.osp=S.or=null; S.more={}; }
  else if(level==="sp"){ S.osp=S.osp===id?null:id; S.or=null; S.more={}; }
  else if(level==="row"){ S.or=S.or===id?null:id; }
  else if(level==="more"){ S.more[id]=(S.more[id]||(id==="search"?CPCS_SPAGE:CPCS_PAGE))+(id==="search"?CPCS_SPAGE:CPCS_PAGE); }
  else if(level==="kind"){ S.kind=id||"all"; S.or=null; S.more={}; }
  else if(level==="f"){ S.f[id]=!S.f[id]; S.or=null; S.more={}; }
  else if(level==="clear"){ S.q=""; S.or=null; S.more={}; }
  else return;
  cpcsRe(level==="clear");
  if(level==="row"&&S.or!=null) cpcsScroll("cpcs-r-"+S.or); else if((level==="st"||level==="grp"||level==="sp")&&id!=null) cpcsScroll(cpcsHid(id));
}
function cpcsSearch(v){ if(!cpcsOn()) return; clearTimeout(_cpcs.qt); const go=()=>{ _cpcs.q=String(v||"").trim(); _cpcs.or=null; _cpcs.more={}; cpcsRe(); }; if(typeof setTimeout==="function") _cpcs.qt=setTimeout(go,180); else go(); }
// a tap paints only the chips and the list, so the search box keeps its focus; anything else repaints the page
function cpcsRe(withSearch){
  if(typeof document!=="undefined"&&document.getElementById){ const L=document.getElementById("cpcs-list"), ch=document.getElementById("cpcs-chips");
    if(L&&ch&&!withSearch){ ch.innerHTML=cpcsChipsHtml(); L.innerHTML=cpcsListHtml(); const x=document.getElementById("cpcs-x"); if(x) x.style.display=_cpcs.q?"":"none"; return; } }
  if(typeof envcRe==="function") envcRe();
}
function cpcsScroll(id){
  if(typeof document==="undefined"||typeof requestAnimationFrame!=="function") return;
  requestAnimationFrame(()=>{ try{ const el=document.getElementById(id), t=document.getElementById("cpcs-tools"); if(!el) return; const r=el.getBoundingClientRect(), top=t?t.getBoundingClientRect().bottom:0;
    if(r.top<top+6||r.top>window.innerHeight-90) window.scrollBy({top:r.top-top-10,behavior:"smooth"}); }catch(e){} });
}
