  if(typeof cptrListHtml==="function"){ const _t=cptrListHtml(M); if(_t!==undefined) return _t; }   // ✂️ CPTRIM: the Trim view while ✂️ Trim is on
  if(!M.ready){ cpcsLoad(); return (_cpcs.err?'<div class="cpcs-note" style="color:#b91c1c">'+cpcsEsc(_cpcs.err)+'</div>':'')+'<div class="cpcs-note">Loading the cards…</div>'; }
  if(cpcsSearching()) return cpcsSearchHtml(M);
