  h+='<div class="cpcs-fold open"><div class="cpcs-fb" style="padding-top:6px">'+list.slice(0,n).map(c=>cpcsRowHtml(c,M,{crumb:((secOf[c.sec]&&secOf[c.sec].label)||c.sec)+" › "+(c.kind==="id"?"ID · "+c.g.label:c.g.label)})).join("");
