  if(s.add) h+=s.hid?'<button class="cpce-btn pri" onclick="cpceShow('+c.i+')">↩ Bring it back</button>':'<button class="cpce-btn red" onclick="cpceHide('+c.i+')">\u{1F648} Take it back</button>';
  else h+=s.hid?'<button class="cpce-btn pri" onclick="cpceShow('+c.i+')">↩ Show again</button>':'<button class="cpce-btn red" onclick="cpceHide('+c.i+')">\u{1F648} Hide for my class</button>';
