function cpceQaClose(){ _cpce.qa=null; cpceRe(); }
function cpceQaFocus(scroll){ try{ const t=document.getElementById(_cpce.qa&&_cpce.qa.paste?"cpce-pt":"cpce-af"); if(t&&t.focus) t.focus(); }catch(e){} if(scroll&&typeof cpcsScroll==="function") cpcsScroll("cpce-qa"); }
