  const fb=(typeof cpskFb==="function")?cpskFb(s.key):String(s.key).replace(/\./g,":"), S=envcStudents().filter(x=>x&&x.summary); let learned=0;
  S.forEach(x=>{ const o=x.summary.skills&&x.summary.skills[s.section], g=o&&o.stage&&o.stage[fb]; if(g==="learned") learned++; });   // summary.skills.<section>.stage (CPSKILL)
