function cptrHiddenSkill(s,mode){ if(!s||mode==="unit"||typeof cpskLayer!=="function") return false; const L=cpskLayer()||{}, fb=(typeof cpskFb==="function")?cpskFb(s.key):s.key; return !!(L[fb]&&L[fb].hide===true); }
