// ── the page
function cptrChipHtml(h){ if(!cptrOn()) return h; cptrCss(); return '<button class="cpcs-chip cptr-chip'+(_cptr.on?' on':'')+'" onclick="cptrToggle()">✂️ Trim</button>'+(_cptr.on?'':'<span class="cpcs-sep">·</span>'+h); }
function cptrToggle(){ if(!cptrOn()) return; _cptr.on=!_cptr.on; _cptr.ask=_cptr.merge=_cptr.shorten=null; if(_cptr.on) cptrStart(); cptrRe(); }
function cptrRe(){ if(typeof cpcsRe==="function") cpcsRe(); }
