  if(r.stage==="shown") h+='<div style="text-align:center;margin-top:12px"><button onclick="cpSkillStep()" style="'+CPSK_BTN+';min-height:52px;padding:0 30px;font-size:16px">'+(r.shown<n?'Next step \u25B6':r.tryIt?'Another example \u25B6':'Got it \u2713')+'</button></div>';
  else if(!r.checked) h+='<div style="text-align:center;margin-top:12px"><button onclick="cpSkillCheckTry()" style="'+CPSK_BTN+';min-height:52px;padding:0 34px;font-size:16px">Check</button></div>';
  else { const c=r.checked; h+='<div style="margin-top:12px;text-align:center;font-size:17px;font-weight:900;color:'+(c.ok?'#15803d':'#dc2626')+'">'+(c.ok?'\u2713 All right!':'\u2717 Missed at step '+(c.step+1)+': '+cpskEsc(cpSkillMissLabel(sk,c.miss)))+'</div>';
    if(r.moved) h+='<div style="text-align:center;font-size:13px;font-weight:800;color:#155e75;margin-top:4px">'+(r.moved==="faded"?'Next: you finish the last step.':r.moved==="solo"?'Next: on your own!':'Next: another worked example.')+'</div>';
    h+='<div style="text-align:center;margin-top:12px"><button onclick="cpSkillNextTry()" style="'+CPSK_BTN+';min-height:52px;padding:0 34px;font-size:16px">'+(r.tries.length<CPSK_SITTING?'Next problem \u25B6':'Finish')+'</button></div>'; }
