    steps.push({id:"math",label:(D.totalLbl||"Total")+" (each count \u00D7 its group’s number, added)",kind:"num",answer:total,work:G.map((g,i)=>steps[i].answer+" \u00D7 "+(+g.weight||0)).join(" + ")+" = "+total});
    const ri=band(total);
