    const r=cpibRun(sk), plan=r?cpibPlan(sk,r,R):null, k=r?(r.n|0):0;
    const form=plan?forms[k%forms.length]:forms[Math.floor(rnd()*forms.length)], want=R.length?(plan?plan.bands[k%R.length]:Math.floor(rnd()*R.length)):-1;
