      if(form==="list"){ const mine=rows.filter(w=>w.g===g.key), n=mine.reduce((a,w)=>a+w.n,0); st.alt=n; st.work=mine.length?mine.length+" kind"+(mine.length===1?"":"s")+(n!==mine.length?" (not "+n+" animals)":"")+": "+mine.map(w=>w.name).join(", "):"none in the sample"; }
      else { const plus=pic.group===g.key; if(plus) st.less=cnt[i]-1; st.work=plus?(cnt[i]-1)+" + the "+(photo?"one in the picture":pic.name)+" = "+cnt[i]:String(cnt[i]); }
