// the site's own kid (a kid or parent login, or the demo's kid) — envClassOverlay's test
function cpAheadOn(kid){ try{ if(!cpahSite()||!kid||typeof _envs==="undefined"||kid!==_envs.kid) return false; return cpahDemo()||_envs.role==="kid"||_envs.role==="parent"; }catch(e){ return false; } }
