// summary.ahead = {days:{<YYYYMMDD>:n} (the last 30 days that have one), total (every card learned ahead), started (every card started ahead)}
function cpAheadSumOf(cards){ const days={}; let total=0; (cards||[]).forEach(c=>{ if(!c||!c.learned) return; total++; days[c.learned]=(days[c.learned]||0)+1; });
  const keep={}; Object.keys(days).sort().slice(-CPAH_DAYS).forEach(k=>{ keep[k]=days[k]; }); return {days:keep,total,started:(cards||[]).length}; }
// cards learned ahead in the last 7 days (the effort board's week) / in all / the team bonus they give
function cpAheadWeek(summary,now){ const d=(summary&&summary.ahead&&summary.ahead.days)||{}; let n=0;
  Object.keys(d).forEach(k=>{ const ago=(typeof envsDaysAgo==="function")?envsDaysAgo(k,now):null; if(ago!=null&&ago>=0&&ago<7) n+=Math.max(0,Math.floor(Number(d[k])||0)); }); return n; }
function cpAheadTotal(summary){ const t=summary&&summary.ahead&&Number(summary.ahead.total); return (Number.isFinite(t)&&t>0)?Math.floor(t):0; }
function cpAheadBonus(summary){ return Math.floor(cpAheadTotal(summary)/CPAH_TEAM_PER); }
// envsBoardsCompute's hook (pure on what it is given): 💪 + 2 per card learned ahead this week (it counts double) and 🚀 on the row; each team
// keeps its gain (envsGain's meaning) and gains a labelled 🚀 bonus (1 per 10 cards learned ahead, per member), ranked on gain + bonus
function cpAheadBoards(students,teams,effort,now){
  const S=students||{}, sm=sid=>((S[sid]||{}).summary)||null;
  (effort||[]).forEach(r=>{ const w=cpAheadWeek(sm(r.sid),now); r.ahead=w; r.aheadPts=CPAH_EFFORT_X*w; r.score=(Number(r.score)||0)+r.aheadPts; });
  (effort||[]).sort((a,b)=>b.score-a.score||String(a.name).localeCompare(String(b.name)));
  (teams||[]).forEach(t=>{ let b=0, n=0, now7=0; (t.members||[]).forEach(sid=>{ b+=cpAheadBonus(sm(sid)); n+=cpAheadTotal(sm(sid)); if(cpAheadWeek(sm(sid),now)>0) now7++; });
    t.bonus=b; t.aheadCards=n; t.aheadNow=now7; t.pts=(Number(t.gain)||0)+b; });
  (teams||[]).sort((a,b)=>b.pts-a.pts||b.gain-a.gain||String(a.name).localeCompare(String(b.name)));
  return {teams,effort}; }
// the boards' words (envsBoardsHtml's hooks; a board published before this block has no bonus fields and reads as before)
function cpAheadTeamPts(t){ return (t&&t.pts!=null)?t.pts:(t?t.gain:0); }
function cpAheadTeamLine(t){ if(!t||!(t.bonus>0||t.aheadCards>0)) return ""; return '<div style="font-size:11px;color:#7c2d12;font-weight:700">'+cpahEsc(t.gain)+' from gains + \u{1F680} '+cpahEsc(t.bonus||0)+' bonus ('+cpahEsc(t.aheadCards||0)+' card'+(t.aheadCards===1?'':'s')+' learned ahead)'+(t.aheadNow?' · \u{1F680} '+t.aheadNow+' getting ahead this week':'')+'</div>'; }
function cpAheadTeamNote(){ return ' \u{1F680} Bonus: +1 for every '+CPAH_TEAM_PER+' cards a member learns beyond the day’s assignment (the gains stay as they are).'; }
function cpAheadEffNote(){ return ' \u{1F680} A card learned beyond the day’s assignment counts double: +'+CPAH_EFFORT_X+' each.'; }
function cpAheadBadge(r){ return (r&&r.ahead>0)?' <span title="cards learned beyond the assignment this week" style="font-size:11px;font-weight:800;color:#7c2d12;background:#ffedd5;border-radius:999px;padding:1px 7px">\u{1F680} ahead</span>':''; }
function cpAheadEffTxt(r){ return (r&&r.ahead>0)?' · \u{1F680} '+r.ahead+' ahead ×'+CPAH_EFFORT_X:''; }
// the summary's hook (envSummary, the site's kid only — Lincoln's mirror gets nothing): summary.ahead, or null when nothing was started ahead
function cpAheadSum(kid,M,u){ try{ if(!cpAheadOn(kid)) return null; M=M||((typeof masteryData!=="undefined"&&masteryData)||{});
  const rec=((M[kid+"_settings"]||{}).ahead_days)||null; if(!rec||typeof rec!=="object"||!Object.keys(rec).length) return null;
  const isDeck={}; ((u&&u.decks)||[]).forEach(d=>{ if(d&&d.key) isDeck[d.key]=1; }); let items=M[kid]; if(!Array.isArray(items)) items=Object.values(items||{});
  return cpAheadSumOf(cpAheadCards(rec,cpahLogByDay((M.studyLog||{})[kid],d=>!!isDeck[d]),items)); }catch(e){ return null; } }
// ── THE KID'S APP ──
function cpahSecs(){ return (typeof envsStations==="function"&&envsStations())||[]; }
function cpahSec(id){ return cpahSecs().find(s=>s.id===id)||null; }
function cpahSession(kid){ let S=[]; try{ S=(typeof mstSessions==="function"&&mstSessions(kid))||[]; }catch(e){ S=[]; } const sid=(typeof ENV_SESSION_SID!=="undefined")?ENV_SESSION_SID:"envirothon"; return S.find(s=>s&&s.sid===sid)||null; }
function cpahIsMine(session){ return !!session&&session.kind==="deck"&&session.sid===((typeof ENV_SESSION_SID!=="undefined")?ENV_SESSION_SID:"envirothon"); }
// the student's own early access {<section>:{at, by}}: the live listener; the demo reads the console's in-memory row (the "server")
function cpahMine(){ try{ if(cpahDemo()){ const s=((typeof _envc!=="undefined"&&_envc.students)||{})[_envs.sid]; return (s&&s.ahead)||{}; } }catch(e){} return _cpah.mine||{}; }
// sent out to this student by the teacher: a release record of the section (or one of its decks / Key Concepts) reached this app — CPSHARE
// notes the first one of each section (memory only)
function cpahSent(kid,sec){ try{ const m=(typeof _cpshare!=="undefined"&&_cpshare.sent&&_cpshare.sent[kid])||null; return !!(m&&m[sec]>0); }catch(e){ return false; } }
// the sections this student opened early that the teacher hasn't sent out (yet), newest first
function cpahEarly(kid){ const mine=cpahMine(), out=[]; Object.keys(mine).forEach(sec=>{ if(mine[sec]&&cpahSec(sec)&&!cpahSent(kid,sec)) out.push({sec,at:Number(mine[sec].at)||0}); }); return out.sort((a,b)=>b.at-a.at); }
function cpahEarlyDecks(kid){ const m={}; cpahEarly(kid).forEach(e=>{ ((cpahSec(e.sec)||{}).decks||[]).forEach(d=>{ if(!(d.key in m)) m[d.key]=e.sec; }); }); return m; }
function cpahDayRec(kid,day){ const st=((typeof masteryData!=="undefined"&&masteryData)||{})[kid+"_settings"]||{}, A=st.ahead_days; return (A&&typeof A==="object"&&A[day||cpahToday()])||null; }
// 🚀 the extra runs today: the student tapped Keep going / Study ahead today and the switch is still on
function cpAheadExtraOn(kid){ return cpAheadOn(kid)&&!!cpahDayRec(kid)&&cpahKidOn(); }
function cpahExtraOf(session){ return Math.max(CPAH_MIN_EXTRA,Math.floor(Number(session&&session.newPerDay)||0)); }
// the cards started ahead that are still being learned (they get seats of their own on the days after)
