function cpAheadBank(kid,cat,all){ try{ if(!Array.isArray(all)||!all.length||!cpAheadOn(kid)) return all; const E=cpahEarlyDecks(kid); if(!E[cat]) return all; return cpAheadExtraOn(kid)?all:[]; }catch(e){ return all; } }
