let CPSC_PREV=(typeof CPSK_TYPES!=="undefined"&&CPSK_TYPES.scale)||null;   // a `scale` maker registered before this block keeps every other data.kind
const CPSC_READS=["diameter","logs"];   // the readings this block draws (research §4.9 #1), in the research's order
