function cpscHers(p,r){ if(!r||!r.checked||!r.checked.wrong) return null; const i=cpscReadAt(p); if(i<0||!r.checked.wrong[i]) return null; const v=cpscNum(p.typed&&p.typed[i]); return (v!=null&&v>0)?v:null; }
