  h+='<div class="cpce-acts">'+(it.hidden?'':'<button class="cpce-btn" onclick="cpctEditOpen(\''+J+'\')">✏️ Edit</button>')+
    (it.hidden?'<button class="cpce-btn pri" onclick="cpctShow(\''+J+'\')">↩ Put back</button>':'<button class="cpce-btn red" onclick="cpctHide(\''+J+'\')">\u{1F648} Remove for my class</button>')+
    '<button class="cpce-btn" onclick="cpctMove(\''+J+'\',-1)"'+(i<=0?' disabled':'')+' aria-label="Move up">↑</button><button class="cpce-btn" onclick="cpctMove(\''+J+'\',1)"'+(i<0||i>=all.length-1?' disabled':'')+' aria-label="Move down">↓</button></div>';
  if(it.hidden) h+='<div class="cpce-was">\u{1F648} Removed for your class: students won’t get it. Anyone who already took the form keeps their score.</div>';
