  if(add) h+='<label class="cpce-lbl" for="cpct-ecite">Cite (optional)</label><input id="cpct-ecite" class="cpce-in" maxlength="'+CPCT_CITE_MAX+'" placeholder="pg. 12, the manual" value="'+E2(d.cite||"")+'" oninput="cpctIn(\'cite\',this.value)">';
  const took=cpctTook(F);
