  h+='<div class="cpce-acts"><button class="cpce-btn pri" onclick="cpctSave()">'+(E.add?'＋ Add':'Save')+'</button><button class="cpce-btn" onclick="cpctEditCancel()">Cancel</button>'+(it&&it.edited&&!it.added?'<button class="cpce-btn" onclick="cpctUseOriginal()">Use the original</button>':'')+'</div></div>';
