const CPM_BEHIND=60, CPM_LIST_MAX=40, CPM_CARDS=5, CPM_PAGE={q:10,w:10,g:8};
const _cpm={sec:"all",form:"both",fold:null,row:null,card:null,more:{},lid:null,fresh:false,show:null,css:false,key:false,demo:null,demoFor:null,raw:null,rawFor:null};
function cpmOn(){ return typeof envcOn==="function"&&envcOn()&&typeof cprAll==="function"&&typeof cpcsIndex==="function"; }
function cpmEsc(v){ return envsEsc(v); }
function cpmJ(v){ return envcJ(v); }
function cpmW(k){ return (typeof cpcsWord==="function")?cpcsWord(k):k; }
function cpmFW(w){ return (typeof cprFW==="function")?cprFW(w):String(w); }
