  let i=chips.findIndex(x=>x&&x[0]==="cptests"); if(i<0) i=chips.findIndex(x=>x&&x[0]==="cpcards"); if(i<0) i=chips.findIndex(x=>x&&x[0]==="grid");
  chips.splice(i+1,0,["cpmissed","⚠️ Most missed"]); return chips;
