  const M=cpcsIndex(), X=cprAll(); if(!M||!M.ready||!X||!X.ready) return false;
  _cpm.demoFor=_envc.demo; const weak={}, kc={};
  cpmStudents().forEach(s=>{ const sm=s.summary||{}, W=weak[s.sid]={}, K=kc[s.sid]={};
    const add=(c,salt)=>{ const have=cpmVals(sm.weak&&sm.weak[c.deck]), L=W[c.deck]=W[c.deck]||[]; if(have.length+L.length>=10||have.some(r=>r.n===c.name)||L.some(r=>r.n===c.name)) return;
      const h=cpmHash(s.sid+"|"+c.id+"|"+salt); L.push({n:c.name,m:1+h%5,d:(h>>>4)%3,t:"daily"}); };
    M.secs.forEach(sec=>{ const st=envsStation(sec.id); if(!st||(typeof cppReleased==="function"&&!cppReleased(sm,st))) return;
      let mm=0, tt=0; st.decks.forEach(d=>{ const r=sm.byDeck&&sm.byDeck[d.key]; if(r&&!r.held){ mm+=+r.mastered||0; tt+=+r.total||0; } }); const base=tt?mm/tt:0;
      sec.cards.forEach(c=>{ const ck=sec.id+"|"+cpmRaw(c); if(K[ck]!=null) return;
        K[ck]=Math.max(0,Math.min(1,base+((cpmHash(ck)%100)/100-0.5)*0.9+((cpmHash(s.sid+ck)%100)/100-0.5)*0.2)); });
      X.forms.filter(f=>f.sk===sec.id).forEach(f=>f.A.rows.forEach(r=>{ if(r.wrong.some(x=>x.sid===s.sid)) (r.cards||[]).slice(0,2).forEach(id=>{ const c=M.byId[id]; if(c) add(c,"q"); }); }));
      const core=sec.cards.filter(c=>c.core); for(let i=0;i<2&&core.length;i++) add(core[cpmHash(s.sid+sec.id+i)%core.length],"c"); }); });
