// ── the taps
function cpmTap(level,id){
  if(!cpmOn()) return; const S=_cpm;
  if(level==="sec"){ S.sec=id||"all"; S.row=S.card=null; S.more={}; }
  else if(level==="form"){ S.form=(id==="pre"||id==="post")?id:"both"; S.row=S.card=null; S.more={}; }
  else if(level==="fold"){ S.fold=S.fold===id?null:id; S.row=S.card=null; }
  else if(level==="row"){ S.row=S.row===id?null:id; S.card=null; }
  else if(level==="card"){ S.card=S.card===id?null:id; }
  else if(level==="more"){ S.more[id]=(S.more[id]||CPM_PAGE[id]||10)+(CPM_PAGE[id]||10); }
  else return;
  if(typeof envcRe==="function") envcRe();
}
// ── 📋 the review list: classes/<cid>/review/<listId>
function cpmLists(){ const R=(typeof _envc!=="undefined"&&_envc.cls&&_envc.cls.review)||{}; return Object.keys(R).filter(k=>R[k]&&typeof R[k]==="object").map(k=>({id:k,name:String(R[k].name||""),items:cpmVals(R[k].items).map(String),at:+R[k].at||0,by:R[k].by||""})).sort((a,b)=>b.at-a.at||a.id.localeCompare(b.id)); }
function cpmCur(){ if(_cpm.fresh) return null; const L=cpmLists(); return L.find(x=>x.id===_cpm.lid)||L[0]||null; }
function cpmItems(){ const c=cpmCur(); return c?c.items:[]; }
function cpmIn(k){ return cpmItems().indexOf(k)>=0; }
function cpmKeyOk(k){ return typeof k==="string"&&k.length<=200&&/^(q|c):\S/.test(k); }
function cpmToday(){ return (typeof envcToday==="function")?envcToday(Date.now()):new Date(Date.now()).toISOString().slice(0,10); }
// PURE: the record one list saves — her name (≤ 60), the items (unique, ≤ CPM_LIST_MAX, keys only), at, by
function cpmRec(name,items,by,now){ const it=[]; (items||[]).forEach(k=>{ if(cpmKeyOk(k)&&it.indexOf(k)<0&&it.length<CPM_LIST_MAX) it.push(k); });
  return {name:String(name==null?"":name).trim().slice(0,60)||"Class review",items:it,at:now,by:String(by||"")}; }
function cpmSave(items,name){
  if(!cpmOn()) return Promise.resolve(null); const cid=_envc.cid; if(!cid) return Promise.resolve(null);
  const cur=cpmCur(), R=(_envc.cls&&_envc.cls.review)||{}; let id=cur?cur.id:"r"+Date.now().toString(36); for(let n=1;!cur&&R[id]&&n<99;n++) id="r"+Date.now().toString(36)+n.toString(36);   // a new list never reuses an id
  const rec=cpmRec(name!=null?name:(cur?cur.name:"Class review "+(typeof cppLbl==="function"?cppLbl(cpmToday()):cpmToday())),items,(typeof _envs!=="undefined"&&_envs.uid)||"",Date.now());
  return envcWrite("classes/"+cid+"/review/"+id,rec).then(()=>{ const C=_envc.cls=_envc.cls||{}; C.review=Object.assign({},C.review||{},{[id]:rec}); _cpm.lid=id; _cpm.fresh=false; envcRe(); return rec; }).catch(()=>null);
}
function cpmToggle(k){ if(!cpmOn()||!cpmKeyOk(k)) return; const L=cpmItems().slice(), i=L.indexOf(k);
  if(i>=0) L.splice(i,1); else { if(L.length>=CPM_LIST_MAX){ envsToast("The list holds "+CPM_LIST_MAX+" items. Start a new list for more."); return; } L.push(k); }
  cpmSave(L).then(r=>{ if(r&&!envsDemo()) envsToast(i>=0?"Taken off the review list":"Added to the review list ("+r.items.length+")"); }); }
function cpmAddMany(keys){ if(!cpmOn()) return; const L=cpmItems().slice(); let n=0; (keys||[]).forEach(k=>{ if(cpmKeyOk(k)&&L.indexOf(k)<0&&L.length<CPM_LIST_MAX){ L.push(k); n++; } });
  if(!n){ envsToast("Already in the review list"); return; } cpmSave(L).then(r=>{ if(r&&!envsDemo()) envsToast("Added "+n+" question"+(n===1?"":"s")+" to the review list"); }); }
