    cpmCss(); if(!o){ o=document.createElement("div"); o.id="cpm-show"; o.className="cpm-show"; o.setAttribute("role","dialog"); o.setAttribute("aria-label","Review on screen"); document.body.appendChild(o); }
    o.innerHTML=cpmShowHtml();
