function cpwkToday(){ return (typeof cppToday==="function")?cppToday():((typeof envcToday==="function")?envcToday(Date.now()):cpwkStr(Date.now())); }
function cpwkMo(s){ return ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"][+cpwkKey(s).slice(4,6)-1]+" "+(+cpwkKey(s).slice(6,8)); }
