// PURE: completion = days studied (no more than planned) ÷ planned; null when nothing was planned
function cpWeekDone(rec){ const p=rec&&rec.planned; if(p==null||!(+p>0)) return null; return Math.round(Math.min(+rec.days||0,+p)/(+p)*100); }
