function cptpStrongMap(S,stns,rankFn){ const out={}; if(typeof rankFn!=="function") return out;
  (stns||[]).filter(st=>st&&st.id!=="general").forEach(st=>{ let rows=[]; try{ rows=rankFn(S,st)||[]; }catch(e){ rows=[]; }
    rows.forEach((r,i)=>{ const o=out[r.sid], x={sec:st.id,rank:i+1,score:r.score,of:rows.length}; if(!o||x.rank<o.rank||(x.rank===o.rank&&x.score>o.score)) out[r.sid]=x; }); });
  return out; }
// the weights in force: classes/<cid>/teamPick/w over the defaults (whole numbers 0–3 only)
function cptpWeights(cls){ const w=Object.assign({},CPTP_W_DEF), W=cls&&cls.teamPick&&cls.teamPick.w;
  if(W&&typeof W==="object") CPTP_CRIT.forEach(c=>{ const v=W[c.k]; if(Number.isInteger(v)&&v>=0&&v<=CPTP_W_MAX) w[c.k]=v; });
  return w; }
function cptpEqual(w){ return CPTP_CRIT.every(c=>w[c.k]===CPTP_W_DEF[c.k]); }
// the combined score: the weighted mean of the criteria the student has → {score, parts:[{k, v, w}], sw}; null when none counts
function cptpScore(v,w){ const parts=CPTP_CRIT.filter(c=>(w[c.k]||0)>0&&v[c.k]!=null).map(c=>({k:c.k,v:v[c.k],w:w[c.k]})), sw=parts.reduce((a,p)=>a+p.w,0);
  return {score:sw?Math.round(parts.reduce((a,p)=>a+p.v*p.w,0)/sw):null,parts,sw}; }
// the working, in one line: "(100×1 + 90×1) ÷ 2 = 95"
function cptpWorking(sc){ if(!sc||sc.score==null) return "nothing to count yet"; return "("+sc.parts.map(p=>p.v+"×"+p.w).join(" + ")+") ÷ "+sc.sw+" = "+sc.score; }
// one student's row (PURE given its inputs)
function cptpRow(s,sc,strong,w,name){ const att=cptpAttOf(sc&&sc.attendance), pres=cptpPresOf(sc), tests=cptpTestsOf(sc,s&&s.summary), study=cptpStudyOf(s), st=strong||null;
  const v={att:att.pct,pres:pres.pct,tests:tests.pct,study:study.pct,strong:st?st.score:null};
  return {sid:s.sid,name:name||String((s.meta&&s.meta.name)||s.sid),att,pres,tests,study,strong:st,v,sc:cptpScore(v,w)}; }
// sorted rows, each with its combined place (ties share it). sort ∈ rank · att · pres · tests · study · strong · name
function cptpRank(rows,sort){ const R=rows.slice(), by=(a,b)=>(a==null)-(b==null)||(b||0)-(a||0);
  R.sort((a,b)=>by(a.sc.score,b.sc.score)||a.name.localeCompare(b.name)); let last=null, place=0;
  R.forEach((r,i)=>{ if(r.sc.score==null){ r.place=null; return; } if(r.sc.score!==last){ place=i+1; last=r.sc.score; } r.place=place; });
  if(sort==="name") R.sort((a,b)=>a.name.localeCompare(b.name));
  else if(sort&&sort!=="rank"&&CPTP_CRIT.some(c=>c.k===sort)) R.sort((a,b)=>{ const x=a.v[sort], y=b.v[sort]; return (x==null)-(y==null)||(y||0)-(x||0)||by(a.sc.score,b.sc.score)||a.name.localeCompare(b.name); });
  return R; }
// the days attendance can be taken: the class meetings up to today (newest first, the last CPTP_DAYS_BACK), plus today
function cptpDays(cls,today){ const M=(typeof cpCalMeetings==="function")?cpCalMeetings(cls):[], out=M.filter(m=>m.date<=today).slice(-CPTP_DAYS_BACK).reverse().map(m=>({date:m.date,what:m.what||(m.sec?cptpSecName(m.sec):""),meet:true}));
  if(!out.some(m=>m.date===today)) out.unshift({date:today,what:"",meet:false}); return out; }
// ── THE CONSOLE ──
function cptpStudents(){ return (typeof envcStudents==="function")?envcStudents():[]; }
function cptpRows(){ if(typeof cpwkDemoSeed==="function") cpwkDemoSeed();   // the demo's older weeks land on the students before they are copied
  const S=cptpStudents(), stns=(typeof envsStations==="function")?envsStations():[], strong=cptpStrongMap(S,stns,(typeof envcStrongRank==="function")?envcStrongRank:null), w=cptpWeights(cptpCls()), SC=(_envc&&_envc.scores)||{};
  return cptpRank(S.map(s=>cptpRow(s,SC[s.sid]||{},strong[s.sid],w,(typeof envcName==="function")?envcName(s):s.sid)),_cptp.sort); }
// the console's chip: 🏅 Team picks right after 📊 Weekly (else after 💪 Who is strong where); the array is the console's, this only splices into it
function cptpChips(chips){
  if(!cptpOn()||!Array.isArray(chips)||chips.some(x=>x&&x[0]==="cpteams")) return chips;
  if(typeof _envc!=="undefined"&&_envc.view!=="cpteams") _cptp.open="";
  let i=chips.findIndex(x=>x&&x[0]==="cpweek"); if(i<0) i=chips.findIndex(x=>x&&x[0]==="strong");
  chips.splice(i<0?chips.length:i+1,0,["cpteams","\u{1F3C5} Team picks"]); return chips;
}
function cptpTap(kind,id){
  if(kind==="sort"){ if(id==="rank"||id==="name"||CPTP_CRIT.some(c=>c.k===id)) _cptp.sort=id; }
  else if(kind==="row") _cptp.open=_cptp.open===id?"":String(id||"");
  else if(kind==="att") _cptp.att=_cptp.att===id?"":(cptpDateOk(id)?id:"");
  else if(kind==="w") _cptp.wOpen=!_cptp.wOpen;
  if(typeof envcRe==="function") envcRe();
}
function cptpRefuse(){ if(typeof envsToast==="function") envsToast("\u{1F512} The team picks are set by "+cptpWho()); return false; }
// the console's memory after a save (demo: this IS the state; live: the listeners confirm it a moment later)
function cptpMem(upd){
  Object.keys(upd).forEach(p=>{ const a=p.split("/").filter(Boolean), v=upd[p];
    if(a[0]==="scores"&&a[3]==="attendance"&&a[4]){ const SC=_envc.scores=_envc.scores||{}, r=SC[a[2]]=Object.assign({},SC[a[2]]||{}), A=r.attendance=Object.assign({},r.attendance||{}); if(v==null) delete A[a[4]]; else A[a[4]]=v; }
    else if(a[0]==="classes"&&a[2]==="teamPick"){ const C=_envc.cls||(_envc.cls={}), T=C.teamPick=Object.assign({},C.teamPick||{}); if(a[3]==="w"&&a[4]){ T.w=Object.assign({},T.w||{}); if(v==null) delete T.w[a[4]]; else T.w[a[4]]=v; } else if(a[3]) T[a[3]]=v; } });
}
// THE SAVE: one update (paths from the root), through envcWrite → envsWrite
function cptpWrite(upd,note){
  if(!cptpOn()||!_envc.cid||!upd||!Object.keys(upd).length) return false;
  if(!cptpCan()) return cptpRefuse();
  envcWrite("/",upd,"update").then(()=>{ cptpMem(upd); if(!cptpDemo()&&note&&typeof envsToast==="function") envsToast(note); if(typeof envcRe==="function") envcRe(); }).catch(()=>{});
  return true;
}
// ✓ Here / ✗ Away for one student on one day (val true | false | null = not taken)
function cptpAttSet(date,sid,val){
  if(!cptpOn()||!cptpDateOk(date)||date>cptpToday()||!((_envc.students||{})[sid])||!(val===true||val===false||val===null)) return false;
  return cptpWrite({["scores/"+_envc.cid+"/"+sid+"/attendance/"+date]:val});
}
// ✓ Everyone else is here: every student not yet taken that day → true, ONE update
function cptpAttRest(date){
  if(!cptpOn()||!cptpDateOk(date)||date>cptpToday()) return false; const SC=_envc.scores||{}, upd={};
  cptpStudents().forEach(s=>{ const A=(SC[s.sid]&&SC[s.sid].attendance)||{}; if(A[date]!==true&&A[date]!==false) upd["scores/"+_envc.cid+"/"+s.sid+"/attendance/"+date]=true; });
  if(!Object.keys(upd).length){ if(typeof envsToast==="function") envsToast("Everyone is taken"); return false; }
  return cptpWrite(upd,"\u{1F64B} "+Object.keys(upd).length+" marked here");
}
// a weight (0–3), or Equal (the defaults); by + at ride in the same update
function cptpWSet(k,n){ n=Number(n);
  if(!cptpOn()||!CPTP_CRIT.some(c=>c.k===k)||!Number.isInteger(n)||n<0||n>CPTP_W_MAX) return false;
  if(cptpWeights(cptpCls())[k]===n){ if(typeof envsToast==="function") envsToast("Nothing changed"); return false; }
  const b="classes/"+_envc.cid+"/teamPick/"; return cptpWrite({[b+"w/"+k]:n,[b+"by"]:(typeof _envs!=="undefined"&&_envs.uid)||"",[b+"at"]:Date.now()},"Weights saved"); }
function cptpWEqual(){ if(!cptpOn()) return false; const w=cptpWeights(cptpCls()); if(cptpEqual(w)){ if(typeof envsToast==="function") envsToast("Nothing changed"); return false; }
  const b="classes/"+_envc.cid+"/teamPick/", upd={}; CPTP_CRIT.forEach(c=>{ if(w[c.k]!==CPTP_W_DEF[c.k]) upd[b+"w/"+c.k]=CPTP_W_DEF[c.k]; }); upd[b+"by"]=(typeof _envs!=="undefined"&&_envs.uid)||""; upd[b+"at"]=Date.now();
  return cptpWrite(upd,"Weights back to equal"); }
// ── the demo: attendance at the sample meetings (all but the newest), a presentation and a test for those without — memory, the first paint only
function cptpHash(s){ s=String(s); let h=5381; for(let i=0;i<s.length;i++) h=((h*33)^s.charCodeAt(i))>>>0; return h; }
function cptpDemoSeed(){
  if(!cptpDemo()||typeof _envc==="undefined"||!_envc.demo||_cptp.seeded===_envc.demo) return false;
  _cptp.seeded=_envc.demo; if(typeof cpcalDemoSeed==="function") cpcalDemoSeed();
  const today=cptpToday(), past=((typeof cpCalMeetings==="function")?cpCalMeetings(_envc.cls):[]).filter(m=>m.date<=today).map(m=>m.date).slice(0,-1);
  const SC=_envc.scores=_envc.scores||{}, sec=((typeof envsStations==="function"?envsStations():[]).find(st=>st.id!=="general")||{}).id||"";
  cptpStudents().forEach(s=>{ const r=SC[s.sid]=Object.assign({},SC[s.sid]||{}), h=cptpHash(s.sid);
    if(!r.attendance){ const A={}; past.forEach((d,i)=>{ A[d]=((h>>>i)%7)!==0; }); if(past.length) r.attendance=A; }
    if(sec&&!cptpScoreRows(r).some(x=>x.presentation!=null)){ const x=r[sec]=Object.assign({},r[sec]||{}); x.presentation=2+(h%4); x.presMax=5; if(x.test==null){ x.test=14+(h%11); x.testMax=25; } } });
  return true;
}
// ── the look
