  let h='<div class="envs-card"><div class="envs-h2" style="margin-bottom:2px">\u{1F3C5} Team picks</div><div class="envs-muted">A ranking to help you pick teams. It never picks, saves or announces a team: you do, and you name them on \u{1F3C6} Boards.</div>'+cptpGoalsHtml();
  h+='<div class="cptp-chips" role="group" aria-label="Sort by"><span class="envs-muted" style="align-self:center">Sort:</span>'+[["rank","\u{1F3C5} Rank"]].concat(CPTP_CRIT.map(c=>[c.k,c.icon+' '+c.short])).concat([["name","A–Z"]]).map(x=>'<button class="'+(srt===x[0]?'on':'')+'" aria-pressed="'+(srt===x[0])+'" onclick="cptpTap(\'sort\',\''+x[0]+'\')">'+cptpEsc(x[1])+'</button>').join("")+'</div></div>';
