// ── what the parent's drill carries: the app's drill builder, the parent-mode session's decks, reviews only
function cpdrDecks(kid){ const s=new Set(); try{ (mstSessions(kid)||[]).forEach(x=>{ if(x&&x.reviewIn==="parent") (x.decks||[]).forEach(d=>s.add(d)); }); }catch(e){} return s; }
