  const sc=i=>{ const k=i.subject+"|"+i.prompt; return (k in W)?W[k]:(i.drop_count||0); };
  const due=cpdtItems(kid).filter(i=>i&&i.status==="active"&&i.prompt&&D.has(i.subject)&&!hold[i.subject]&&mastIsDue(i,pn));
